#include <bits/stdc++.h>
using namespace std;

struct Mod998 {
    static const long long MOD = 998;
    long long inv[1000001];

    Mod998() {
        inv[1] = 1;
        for (int i = 2; i <= 1000000; i++) {
            inv[i] = MOD - (MOD / i) * inv[MOD % i] % MOD;
        }
    }

    long long add(long long a, long long b) {
        return (a + b) % MOD;
    }

    long long mult(long long a, long long b) {
        return (a * b) % MOD;
    }

    long long div(long long a, long long b) {
        return mult(a, smallInv(b));
    }

    long long smallInv(long long a) {
        long long res = 1, e = MOD - 2;
        long long base = a % MOD;
        while (e > 0) {
            if (e & 1) res = mult(res, base);
            base = mult(base, base);
            e >>= 1;
        }
        return res;
    }

    long long paritySign(int x) {
        return (x % 2 == 0) ? 1 : -1;
    }

    long long ncr(int n, int r) {
        static long long fact[1000001], invFact[1000001];
        static bool initialized = false;
        if (!initialized) {
            fact[0] = 1;
            for (int i = 1; i <= 1000000; i++) {
                fact[i] = mult(fact[i - 1], i);
            }
            invFact[1000000] = smallInv(fact[1000000]);
            for (int i = 999999; i >= 0; i--) {
                invFact[i] = mult(invFact[i + 1], i + 1);
            }
            initialized = true;
        }
        if (r < 0 || r > n) return 0;
        return mult(fact[n], mult(invFact[r], invFact[n - r]));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalCards, totalShuffles;
    cin >> totalCards >> totalShuffles;

    Mod998 mod;

    // Compute modular inverse of totalCards + totalShuffles
    int sum = totalCards + totalShuffles;
    long long invSum = mod.smallInv(sum);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        long long denom = mod.smallInv(totalShuffles + totalCards - i);
        p = mod.mult(p, totalCards - i);
        p = mod.mult(p, denom);
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= totalCards; k++) {
        long long sign = mod.paritySign(k + 1);
        long long numPhases = mod.div(totalShuffles + k, k);
        long long comb = mod.ncr(totalCards, k);
        long long term = sign;
        term = mod.mult(term, comb);
        term = mod.mult(term, numPhases);
        term = mod.mult(term, phaseSize);
        answer = mod.add(answer, term);
    }

    cout << answer << "\n";

    return 0;
}

